/**
 * generated by stackra gen from src/web.module.ts, src/app.error.tsx,
 * src/config/{i18n,theming,csp}.config.ts, assets/public/logo.svg, gen/i18n.ts and middleware.ts
 * — do not edit
 * Purpose: the document shell: `<html lang dir>` from the request's locale mount, the head (favicon
 *          from the logo, theme colour, the stylesheet, preconnects to the image origins the CSP
 *          allows, default meta), then the contexts `createApp` mounts from the config classes in
 *          graph order (flags, theme, i18n, consent, analytics, telemetry, then the UI kit with its
 *          toasts), and the root error boundary, `src/app.error.tsx`. Every script React Router
 *          writes carries the request's CSP nonce, minted by the root middleware.
 * Boundary: config classes are resolved from the container (`ctx.config` in the loader, `useConfig`
 *           in components), never read as statics. The root data is the locale and its catalogues,
 *           so it revalidates only when the locale mount changes; the mount is read from the path
 *           with React Router's `.data` suffix stripped, and the locales are i18n.config.ts values
 *           copied at gen time. The boundary renders; it never reports (the entries report each
 *           error once). The brand fonts are system-installed families, so nothing is preloaded.
 * Runtime: isomorphic
 */
import {
  Links,
  Meta,
  Outlet,
  Scripts,
  ScrollRestoration,
  useRouteLoaderData,
  type ShouldRevalidateFunction,
} from "react-router";
import { Contexts } from "@stackra/app/react";
import { useConfig } from "@stackra/config/react";
import { CspConfig } from "@stackra/csp";
import { useNonce } from "@stackra/csp/react";
import { I18nConfig } from "@stackra/i18n";
import { routeContext } from "@stackra/navigation/router";
import { ColorScheme, ThemingConfig } from "@stackra/theming";
import type { Route } from "./+types/root";
import { AppErrorBoundary } from "#src/app.error";
import appStyles from "#src/styles/app.css?url";
import { loadMessages } from "#stackra/i18n";
import { routeKeys } from "./context";
import { middleware as edgeMiddleware } from "./middleware";

/** i18n.config.ts: the default locale is unprefixed, every other locale has its own mount. */
const PREFIXED_LOCALES = ["ar"] as const;

/** The nonce, the CSP header and the HTML rules, then the 404 redirect lookup (middleware.ts). */
export const middleware: Route.MiddlewareFunction[] = edgeMiddleware;

/** The locale of the matched mount and its catalogues, so SSR and hydration share one `t()`. */
export async function loader(args: Route.LoaderArgs) {
  const ctx = routeContext(args, routeKeys);
  const rtl = ctx.config(I18nConfig).rtl.includes(ctx.locale);
  const messages = await loadMessages(ctx.locale, ["web", "leads", "catalogue", "experience"]);
  return { locale: ctx.locale, dir: rtl ? "rtl" : "ltr", messages } as const;
}

/** The mount a path belongs to: a prefixed locale's code, or `default`. */
function mountOf(url: URL): string {
  const path = url.pathname.replace(/\.data$/, "");
  return (
    PREFIXED_LOCALES.find((locale) => path === `/${locale}` || path.startsWith(`/${locale}/`)) ??
    "default"
  );
}

/** The root data depends on the locale alone; a navigation or a submit inside a mount keeps it. */
export const shouldRevalidate: ShouldRevalidateFunction = ({ currentUrl, nextUrl }) =>
  mountOf(currentUrl) !== mountOf(nextUrl);

/** The favicon from theming.config.ts `logo`, then the stylesheet. */
export const links: Route.LinksFunction = () => [
  { rel: "icon", href: "/favicon.svg", type: "image/svg+xml" },
  { rel: "stylesheet", href: appStyles },
];

/**
 * Renders on success and on error alike, so the error page still has lang, dir, styles and the
 * contexts.
 */
export function Layout({ children }: { children: React.ReactNode }) {
  const theming = useConfig(ThemingConfig);
  const i18n = useConfig(I18nConfig);
  const csp = useConfig(CspConfig);
  const nonce = useNonce();
  const root = useRouteLoaderData<typeof loader>("root");
  const scheme = theming.defaultScheme === ColorScheme.System ? undefined : theming.defaultScheme;
  return (
    <html lang={root?.locale ?? i18n.defaultLocale} dir={root?.dir ?? "ltr"} data-theme={scheme}>
      <head>
        <meta charSet="utf-8" />
        <meta name="viewport" content="width=device-width, initial-scale=1" />
        <meta
          name="theme-color"
          media="(prefers-color-scheme: light)"
          content={theming.themeColor.light}
        />
        <meta
          name="theme-color"
          media="(prefers-color-scheme: dark)"
          content={theming.themeColor.dark}
        />
        {csp.extraImgSrc.map((origin) => (
          <link key={origin} rel="preconnect" href={origin} crossOrigin="anonymous" />
        ))}
        <Meta />
        <Links />
      </head>
      <body className="bg-background text-ink">
        {children}
        <ScrollRestoration nonce={nonce} />
        <Scripts nonce={nonce} />
      </body>
    </html>
  );
}

/** The contexts of the config classes in graph order, with the request's locale and catalogues. */
export default function Root({ loaderData }: Route.ComponentProps) {
  return (
    <Contexts locale={loaderData.locale} messages={loaderData.messages}>
      <Outlet />
    </Contexts>
  );
}

/**
 * Every route and the site layout bubble here (`src/app.error.tsx`). It only renders: the server
 * entry and the browser entry have already reported the error.
 */
export function ErrorBoundary() {
  return <AppErrorBoundary />;
}
